"import { z } from "zod";

export const BrandColorSchema = z.object({
  primary: z.string().default("#6366F1"),
  secondary: z.string().default("#4F46E5"),
  accent: z.string().default("#10B981"),
  background: z.string().default("#0B0F19"),
  text: z.string().default("#F9FAFB"),
  muted: z.string().default("#9CA3AF"),
});

export const BrandSchema = z.object({
  name: z.string(),
  tagline: z.string().optional(),
  logo: z.string().optional(),
  colors: BrandColorSchema.default({}),
  font: z.string().default("Inter, system-ui, sans-serif"),
});

export type Brand = z.infer<typeof BrandSchema>;
export type BrandColors = z.infer<typeof BrandColorSchema>;
"

"import { z } from "zod";
import { ElementSchema } from "./primitives";

export const SceneBackgroundSchema = z.object({
  type: z.enum(["solid", "gradient", "mesh"]).default("gradient"),
  color: z.string().default("brand.background"),
  gradientTo: z.string().optional(),
  angle: z.number().default(135),
  glowOrb: z.boolean().default(true).describe("Subtle floating ambient glow orb in brand accent/primary color"),
});

export const SceneTransitionSchema = z.object({
  type: z.enum(["none", "fade", "slide-left", "slide-up", "zoom-out"]).default("fade"),
  durationFrames: z.number().default(10),
});

export const SceneSchema = z.object({
  id: z.string(),
  name: z.string().optional(),
  durationFrames: z.number().describe("Duration in frames (e.g. 90 frames = 3 seconds at 30fps)"),
  background: SceneBackgroundSchema.default({}),
  elements: z.array(ElementSchema).default([]),
  transition: SceneTransitionSchema.default({}),
});

export type Scene = z.infer<typeof SceneSchema>;
export type SceneBackground = z.infer<typeof SceneBackgroundSchema>;
export type SceneTransition = z.infer<typeof SceneTransitionSchema>;
"

"import { z } from "zod";
import { BrandSchema } from "./brand";
import { SceneSchema } from "./scene";

export const CompositionMetaSchema = z.object({
  title: z.string().default("Motion Ad"),
  fps: z.number().default(30),
  width: z.number().default(1080),
  height: z.number().default(1920),
});

export const AudioTrackSchema = z.object({
  src: z.string(),
  volume: z.number().min(0).max(1).default(0.8),
  loop: z.boolean().default(true),
  fadeInFrames: z.number().default(15),
  fadeOutFrames: z.number().default(20),
});

export const MotionIRSchema = z.object({
  id: z.string(),
  meta: CompositionMetaSchema.default({}),
  brand: BrandSchema,
  audio: AudioTrackSchema.optional(),
  scenes: z.array(SceneSchema),
});

export type MotionIR = z.infer<typeof MotionIRSchema>;
export type CompositionMeta = z.infer<typeof CompositionMetaSchema>;
export type AudioTrack = z.infer<typeof AudioTrackSchema>;
