"import React from "react";
import { Brand, Element, Scene } from "../schema";
import {
  AppWindow,
  CTAButton,
  FeaturePills,
  KineticText,
  LogoReveal,
  MetricCounter,
  SceneTransition,
} from "../primitives";

interface Props {
  scene: Scene;
  brand: Brand;
}

export const SceneRenderer: React.FC<Props> = ({ scene, brand }) => {
  const renderElement = (el: Element) => {
    switch (el.type) {
      case "kinetic-text":
        return <KineticText key={el.id} props={el.props} brand={brand} />;
      case "app-window":
        return <AppWindow key={el.id} props={el.props} brand={brand} />;
      case "logo-reveal":
        return <LogoReveal key={el.id} props={el.props} brand={brand} />;
      case "metric-counter":
        return <MetricCounter key={el.id} props={el.props} brand={brand} />;
      case "feature-pills":
        return <FeaturePills key={el.id} props={el.props} brand={brand} />;
      case "cta-button":
        return <CTAButton key={el.id} props={el.props} brand={brand} />;
      default:
        return null;
    }
  };

  return (
    <SceneTransition
      background={scene.background}
      transition={scene.transition}
      durationFrames={scene.durationFrames}
      brand={brand}
    >
      {scene.elements.map(renderElement)}
    </SceneTransition>
  );
};
"

"import React from "react";
import { Audio, Series } from "remotion";
import { MotionIR, MotionIRSchema } from "../schema";
import { SceneRenderer } from "./SceneRenderer";

interface Props {
  motionIR: MotionIR;
}

export const AdComposition: React.FC<Props> = ({ motionIR }) => {
  // Validate and parse props safely against schema
  const parsed = MotionIRSchema.parse(motionIR);
  const { brand, scenes, audio } = parsed;

  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        backgroundColor: brand.colors.background || "#0B0F19",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Background audio track if configured */}
      {audio?.src && (
        <Audio
          src={audio.src}
          volume={audio.volume ?? 0.8}
        />
      )}

      {/* Sequential Scenes */}
      <Series>
        {scenes.map((scene) => (
          <Series.Sequence
            key={scene.id}
            durationInFrames={scene.durationFrames}
          >
            <SceneRenderer scene={scene} brand={brand} />
          </Series.Sequence>
        ))}
      </Series>
    </div>
  );
};
