"import React from "react";
import { Composition } from "remotion";
import { AdComposition } from "./compositions/AdComposition";
import { MotionIR } from "./schema";
import defaultAd from "../examples/saas-product-ad.json";

export const Root: React.FC = () => {
  const typedDefaultAd = defaultAd as unknown as MotionIR;
  const defaultTotalFrames = typedDefaultAd.scenes.reduce(
    (acc, scene) => acc + scene.durationFrames,
    0
  );

  return (
    <>
      <Composition
        id="AdComposition"
        component={AdComposition}
        durationInFrames={defaultTotalFrames}
        fps={typedDefaultAd.meta.fps || 30}
        width={typedDefaultAd.meta.width || 1080}
        height={typedDefaultAd.meta.height || 1920}
        defaultProps={{
          motionIR: typedDefaultAd,
        }}
        calculateMetadata={async ({ props }) => {
          const ir = (props?.motionIR as MotionIR) || typedDefaultAd;
          const totalFrames = ir.scenes.reduce(
            (acc, s) => acc + (s.durationFrames || 90),
            0
          );
          return {
            durationInFrames: totalFrames,
            fps: ir.meta?.fps || 30,
            width: ir.meta?.width || 1080,
            height: ir.meta?.height || 1920,
          };
        }}
      />
    </>
  );
};
