export class GeminiClient {
  private apiKey: string;

  constructor() {
    this.apiKey = process.env.GEMINI_API_KEY || "";
  }

  hasKey(): boolean {
    return !!this.apiKey && this.apiKey.length > 5;
  }

  async generateStructuredJSON<T>(systemPrompt: string, userPrompt: string): Promise<T> {
    if (!this.hasKey()) {
      throw new Error("No GEMINI_API_KEY configured.");
    }

    const isBearer = this.apiKey.startsWith("AQ.") || this.apiKey.startsWith("ya29.");
    const url = isBearer
      ? "https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent"
      : `https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key=${this.apiKey}`;

    const headers: Record<string, string> = {
      "Content-Type": "application/json",
    };

    if (isBearer) {
      headers["Authorization"] = `Bearer ${this.apiKey}`;
    }

    const payload = {
      system_instruction: {
        parts: [{ text: `${systemPrompt}\n\nYou must reply ONLY with valid RFC8259 JSON.` }],
      },
      contents: [
        {
          role: "user",
          parts: [{ text: userPrompt }],
        },
      ],
      generationConfig: {
        temperature: 0.6,
        responseMimeType: "application/json",
      },
    };

    const resp = await fetch(url, {
      method: "POST",
      headers,
